content.starter:
# 1) Блок terraform: перечисляем нужные провайдеры
terraform {
  required_providers {
    # local = {
    #   source  = "hashicorp/local"
    #   version = "~> 2.5"
    # }
  }
}

# 2) Настройка провайдера. Для local настраивать нечего, но блок оставляем.
# provider "local" {}

# 3) Ресурс: файл на диске.
# Синтаксис: resource "<тип>" "<локальное_имя>" { ... }
# resource "local_file" "hello" {
#   filename = "..."
#   content  = "..."
# }

content.solution:
terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

provider "local" {}

resource "local_file" "hello" {
  filename = "hello.txt"
  content  = "Привет от Terraform!\n"
}

content.starter:
# 1) Переменная с именем файла (со значением по умолчанию)
# variable "file_name" {
#   description = "Имя создаваемого файла"
#   type        = string
#   default     = "hello.txt"
# }

# 2) Переменная с текстом (значение придёт из tfvars)
# variable "message" {
#   ...
# }

# 3) Ресурс использует переменные через var.<имя>
# resource "local_file" "hello" {
#   filename = var.file_name
#   content  = var.message
# }

content.solution:
variable "file_name" {
  description = "Имя создаваемого файла"
  type        = string
  default     = "hello.txt"
}

variable "message" {
  description = "Текст внутри файла"
  type        = string
}

resource "local_file" "hello" {
  filename = var.file_name
  content  = var.message
}

content.starter:
# 1. Заполните блок locals. name_prefix соберите из project и environment.
locals {
  project     = "shop"
  environment = "dev"
  # name_prefix = ...
}

# 2. Этот ресурс уже готов — он опирается на local.name_prefix.
resource "local_file" "note" {
  filename = "${local.name_prefix}.txt"
  content  = "note for ${local.project}"
}

# 3. Добавьте сюда два output: file_name и name_prefix (с description).

content.solution:
locals {
  project     = "shop"
  environment = "dev"
  name_prefix = "${local.project}-${local.environment}"
}

resource "local_file" "note" {
  filename = "${local.name_prefix}.txt"
  content  = "note for ${local.project}"
}

output "file_name" {
  value = local_file.note.filename
}

output "name_prefix" {
  value       = local.name_prefix
  description = "Общий префикс имён"
}

content.starter:
# 1. Опишите переменную environment (string, default = "dev").
variable "environment" {
  # ...
}

# 2. Подключите модуль web из локальной папки ./modules/server
#    и передайте ему name и environment.
module "web" {
  # source = ...
  # ...
}

# 3. Верните адрес наружу через output web_address (module.web.ip_address).

content.solution:
variable "environment" {
  type    = string
  default = "dev"
}

module "web" {
  source      = "./modules/server"
  name        = "web-1"
  environment = var.environment
}

output "web_address" {
  value = module.web.ip_address
}
